/**
 * Secure Authentication & Rate Limiting Handler
 * ---------------------------------------------
 * Self-contained, dependency-free (Node.js `crypto` only) production implementation of:
 *   - Password hashing / verification (scrypt with per-password random salt, constant-time compare)
 *   - JWT (HS256/HS384/HS512) creation & verification with base64url encoding
 *   - Login handler with:
 *       * strict input validation & normalization
 *       * per-IP and per-account sliding-window rate limiting
 *       * exponential-backoff account lockout on repeated failures
 *       * timing-attack resistance (dummy hash verification for unknown users)
 *       * uniform error responses that never leak account existence
 *       * refresh tokens, audit logging and security headers
 *
 * Zero external runtime dependencies. Works on Node.js >= 14.
 */

import {
  randomBytes,
  randomUUID,
  scrypt as _scrypt,
  timingSafeEqual,
  createHmac,
  createHash,
} from 'crypto';

/* ============================================================================
 * Public types
 * ==========================================================================*/

export interface TokenPayload {
  id: string;
  email: string;
  role?: string;
}

export interface JwtClaims extends TokenPayload {
  sub: string;
  iat: number;
  exp: number;
  nbf: number;
  jti: string;
  iss?: string;
  aud?: string;
  typ?: 'access' | 'refresh';
  [key: string]: unknown;
}

export interface LoginRequest {
  email?: string;
  password?: string;
  ip?: string;
  userAgent?: string;
  totp?: string;
}

export interface HttpResponse<T = any> {
  status: number;
  body: T;
  headers?: Record<string, string>;
}

export interface UserRecord {
  id: string;
  email: string;
  passwordHash: string;
  role?: string;
  disabled?: boolean;
  emailVerified?: boolean;
  mfaSecret?: string | null;
  createdAt?: number;
  updatedAt?: number;
  failedLoginCount?: number;
  lastLoginAt?: number | null;
  [key: string]: unknown;
}

export interface UserStore {
  findByEmail(email: string): Promise<UserRecord | null> | UserRecord | null;
  updateUser?(
    id: string,
    patch: Partial<UserRecord>
  ): Promise<void> | void;
}

export interface RateLimitDecision {
  allowed: boolean;
  remaining: number;
  limit: number;
  retryAfterMs: number;
  resetAtMs: number;
}

export interface RateLimitRule {
  /** Maximum number of hits permitted within the window. */
  limit: number;
  /** Sliding window length in milliseconds. */
  windowMs: number;
}

export interface LockoutPolicy {
  /** Consecutive failures before the first lockout kicks in. */
  threshold: number;
  /** Base lock duration (ms) applied at the threshold. */
  baseDurationMs: number;
  /** Multiplier applied per extra failure beyond the threshold. */
  factor: number;
  /** Hard ceiling for a single lock duration (ms). */
  maxDurationMs: number;
  /** Failure counters older than this (ms) are forgotten. */
  failureTtlMs: number;
}

export interface PasswordPolicy {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireDigit: boolean;
  requireSymbol: boolean;
  /** Lower-cased list of forbidden / breached passwords. */
  blocklist: string[];
}

export type JwtAlgorithm = 'HS256' | 'HS384' | 'HS512';

export interface AuthServiceOptions {
  users?: UserRecord[] | UserStore;
  jwtSecret?: string;
  refreshSecret?: string;
  issuer?: string;
  audience?: string;
  algorithm?: JwtAlgorithm;
  accessTokenTtlSec?: number;
  refreshTokenTtlSec?: number;
  clockToleranceSec?: number;
  ipRateLimit?: Partial<RateLimitRule>;
  accountRateLimit?: Partial<RateLimitRule>;
  globalRateLimit?: Partial<RateLimitRule>;
  lockout?: Partial<LockoutPolicy>;
  passwordPolicy?: Partial<PasswordPolicy>;
  scrypt?: Partial<ScryptParams>;
  /** Injectable clock for deterministic testing. */
  now?: () => number;
  /** Injectable audit sink. */
  logger?: (entry: AuditEntry) => void;
  /** Minimum wall-clock duration (ms) of a login attempt (anti-enumeration). */
  minResponseMs?: number;
  /** Trust `X-Forwarded-For`-derived IPs verbatim. */
  trustProxy?: boolean;
  /** Require `emailVerified === true` to log in. */
  requireVerifiedEmail?: boolean;
}

export interface ScryptParams {
  /** CPU/memory cost (must be a power of two). */
  N: number;
  /** Block size. */
  r: number;
  /** Parallelization. */
  p: number;
  /** Derived key length in bytes. */
  keyLength: number;
  /** Salt length in bytes. */
  saltLength: number;
  /** scrypt maxmem, must exceed 128 * N * r. */
  maxmem: number;
}

export interface AuditEntry {
  event:
    | 'login_success'
    | 'login_failure'
    | 'login_invalid_input'
    | 'rate_limited'
    | 'account_locked'
    | 'account_disabled'
    | 'email_unverified'
    | 'mfa_required'
    | 'mfa_failed'
    | 'token_issued'
    | 'token_rejected'
    | 'password_hashed'
    | 'error';
  at: number;
  ip?: string;
  emailHash?: string;
  userId?: string;
  reason?: string;
  meta?: Record<string, unknown>;
}

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(
    payload: { id: string; email: string; role?: string },
    secret: string
  ): Promise<string>;
  handleLogin(request: {
    email?: string;
    password?: string;
    ip?: string;
  }): Promise<{ status: number; body: any }>;
}

/* ============================================================================
 * Errors
 * ==========================================================================*/

export class AuthError extends Error {
  readonly status: number;
  readonly code: string;
  readonly details?: unknown;

  constructor(code: string, message: string, status = 400, details?: unknown) {
    super(message);
    this.name = 'AuthError';
    this.code = code;
    this.status = status;
    this.details = details;
    Object.setPrototypeOf(this, AuthError.prototype);
  }
}

export class ValidationError extends AuthError {
  constructor(message: string, details?: unknown) {
    super('VALIDATION_ERROR', message, 400, details);
    this.name = 'ValidationError';
  }
}

export class RateLimitError extends AuthError {
  readonly retryAfterMs: number;
  constructor(message: string, retryAfterMs: number) {
    super('RATE_LIMITED', message, 429, { retryAfterMs });
    this.name = 'RateLimitError';
    this.retryAfterMs = retryAfterMs;
  }
}

export class TokenError extends AuthError {
  constructor(message: string, code = 'INVALID_TOKEN') {
    super(code, message, 401);
    this.name = 'TokenError';
  }
}

/* ============================================================================
 * Small utilities
 * ==========================================================================*/

const scryptAsync = (
  password: string | Buffer,
  salt: Buffer,
  keylen: number,
  options: { N: number; r: number; p: number; maxmem: number }
): Promise<Buffer> =>
  new Promise((resolve, reject) => {
    _scrypt(password, salt, keylen, options, (err, derived) => {
      if (err) reject(err);
      else resolve(derived as Buffer);
    });
  });

export function base64UrlEncode(input: Buffer | string): string {
  const buf = typeof input === 'string' ? Buffer.from(input, 'utf8') : input;
  return buf
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

export function base64UrlDecode(input: string): Buffer {
  if (typeof input !== 'string' || !/^[A-Za-z0-9_-]*$/.test(input)) {
    throw new TokenError('Malformed base64url segment', 'MALFORMED_TOKEN');
  }
  const pad = input.length % 4 === 0 ? '' : '='.repeat(4 - (input.length % 4));
  return Buffer.from(input.replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64');
}

/** Constant-time string/Buffer comparison that never throws on length mismatch. */
export function safeEqual(a: string | Buffer, b: string | Buffer): boolean {
  const ba = Buffer.isBuffer(a) ? a : Buffer.from(String(a), 'utf8');
  const bb = Buffer.isBuffer(b) ? b : Buffer.from(String(b), 'utf8');
  // Hash both to a fixed length so length differences do not leak via timing.
  const ha = createHash('sha256').update(ba).digest();
  const hb = createHash('sha256').update(bb).digest();
  return timingSafeEqual(ha, hb) && ba.length === bb.length;
}

const EMAIL_RE =
  /^(?=.{3,254}$)[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$/;

export function isValidEmail(email: unknown): email is string {
  return typeof email === 'string' && EMAIL_RE.test(email.trim());
}

/** Normalizes an email for lookup: trims, lowercases domain + local part. */
export function normalizeEmail(email: string): string {
  const trimmed = email.trim();
  const at = trimmed.lastIndexOf('@');
  if (at < 0) return trimmed.toLowerCase();
  const local = trimmed.slice(0, at);
  const domain = trimmed.slice(at + 1).toLowerCase();
  return `${local.toLowerCase()}@${domain}`;
}

/** Removes ASCII control characters & zero-width chars that can be used to smuggle payloads. */
export function sanitizeString(value: string): string {
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u001F\u007F\u200B-\u200D\uFEFF]/g, '');
}

