/**
 * Secure Authentication & Rate Limiting Handler
 *
 * Self-contained production module implementing:
 *  - scrypt password hashing (Node built-in crypto, no external deps) with
 *    timing-safe verification
 *  - HS256 JWT minting with short-lived access tokens (15 min)
 *  - Brute-force protection: per-IP and per-account sliding-window rate limits
 *    plus progressive lockout
 *  - Zero user enumeration: uniform generic errors + dummy hash verification
 *    so response timing does not leak account existence
 *  - Structured JSON logging with correlation IDs and secret masking
 *  - httpOnly / Secure / SameSite=Strict cookie directives for tokens
 *
 * Dependency injection is used for the user repository, rate-limit store, clock
 * and logger so the service scales across multiple process instances (inject a
 * Redis-backed store in production).
 */

import crypto from 'node:crypto';

/* -------------------------------------------------------------------------- */
/* Public contract                                                            */
/* -------------------------------------------------------------------------- */

export interface TokenPayload {
  id: string;
  email: string;
  role?: string;
}

export interface LoginRequest {
  email?: string;
  password?: string;
  ip?: string;
}

export interface LoginResponse {
  status: number;
  body: any;
  headers?: Record<string, string>;
  cookies?: string[];
}

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: TokenPayload, secret: string): Promise<string>;
  handleLogin(request: LoginRequest): Promise<{ status: number; body: any }>;
}

/* -------------------------------------------------------------------------- */
/* Errors                                                                     */
/* -------------------------------------------------------------------------- */

export class AppError extends Error {
  constructor(
    message: string,
    public readonly statusCode: number = 500,
    public readonly code: string = 'INTERNAL_SERVER_ERROR',
  ) {
    super(message);
    this.name = 'AppError';
    Error.captureStackTrace?.(this, AppError);
  }
}

export class ValidationError extends AppError {
  constructor(message: string) {
    super(message, 400, 'VALIDATION_ERROR');
    this.name = 'ValidationError';
  }
}

/* -------------------------------------------------------------------------- */
/* Ports (dependency injection)                                               */
/* -------------------------------------------------------------------------- */

export interface AuthUserRecord {
  id: string;
  email: string;
  passwordHash: string;
  role?: string;
  isActive?: boolean;
}

export interface UserRepository {
  /** MUST perform a case-insensitive lookup on the normalized email. */
  findByEmail(email: string): Promise<AuthUserRecord | null>;
}

/**
 * Sliding-window counter store. Implement with Redis in production:
 *   INCR key + EXPIRE key windowMs (atomic via MULTI or Lua).
 */
export interface RateLimitStore {
  /** Increments the counter for `key` and returns the new count + reset epoch ms. */
  increment(key: string, windowMs: number): Promise<{ count: number; resetAt: number }>;
  /** Current counter state without mutating it. */
  peek(key: string): Promise<{ count: number; resetAt: number } | null>;
  /** Drops the counter (called after a successful login). */
  reset(key: string): Promise<void>;
}

export interface Logger {
  info(message: string, meta?: Record<string, unknown>): void;
  warn(message: string, meta?: Record<string, unknown>): void;
  error(message: string, meta?: Record<string, unknown>): void;
}

export interface AuthServiceOptions {
  users: UserRepository;
  store?: RateLimitStore;
  logger?: Logger;
  now?: () => number;
