  accountMaxAttempts?: number;
  /** Sliding window length in ms (default 15 min). */
  windowMs?: number;
  /** Lockout duration in ms once the account limit is exceeded (default 15 min). */
  lockoutMs?: number;
  /** scrypt cost parameter N (default 2^15 = 32768). */
  scryptCost?: number;
