const SCRYPT_SALT_BYTES = 16;
const SCRYPT_BLOCK_SIZE = 8;
const SCRYPT_PARALLELIZATION = 1;
const DEFAULT_SCRYPT_COST = 32768; // 2^15 — OWASP-recommended minimum for scrypt
const HASH_PREFIX = 'scrypt';

const MIN_PASSWORD_LENGTH = 12;
const MAX_PASSWORD_LENGTH = 200; // bound work factor -> DoS protection
