const DEFAULT_WINDOW_MS = 15 * 60 * 1000;
const DEFAULT_LOCKOUT_MS = 15 * 60 * 1000;
const DEFAULT_IP_MAX = 20;
const DEFAULT_ACCOUNT_MAX = 5;
const DEFAULT_ACCESS_TTL_SECONDS = 900;

/** OWASP-aligned production response headers. */
export const SECURITY_HEADERS: Readonly<Record<string, string>> = Object.freeze({
  'Content-Security-Policy': "default-src 'self'",
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'Cache-Control': 'no-store',
  Pragma: 'no-cache',
});

/**
 * Pre-computed scrypt hash of an unguessable random value. Verified whenever the
 * account does not exist so that the CPU cost — and therefore the response
 * latency — is identical for existing and non-existing accounts.
 */
const DUMMY_HASH = buildDummyHash();

/* -------------------------------------------------------------------------- */
/* Internal helpers                                                           */
/* -------------------------------------------------------------------------- */

function buildDummyHash(): string {
  // Low cost on purpose: this constant is generated at module load (startup),
  // never used for authentication, and only exists to keep the code path warm.
  const salt = crypto.randomBytes(SCRYPT_SALT_BYTES);
  const derived = crypto.scryptSync(crypto.randomBytes(32), salt, SCRYPT_KEYLEN, {
    N: 16384,
    r: SCRYPT_BLOCK_SIZE,
    p: SCRYPT_PARALLELIZATION,
    maxmem: 256 * 1024 * 1024,
  });
  return [
    HASH_PREFIX,
    String(DEFAULT_SCRYPT_COST),
    String(SCRYPT_BLOCK_SIZE),
    String(SCRYPT_PARALLELIZATION),
    salt.toString('base64url'),
    derived.toString('base64url'),
  ].join('$');
