function timingSafeCompare(a: Buffer, b: Buffer): boolean {
  // Length is compared first because timingSafeEqual throws on mismatch. Hash
  // lengths are not secret, so this leaks nothing exploitable.
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

